// Advisory model changes check order only. All rejects have exact final-state witnesses.
const TAIL:usize=96;
type PointTriple=((U256,U256),(U256,U256),(U256,U256));
struct Packet{keys:Vec<u8>,next:usize,batches:Vec<Vec<PointTriple>>}
impl Packet{
 fn ensure(&mut self,batch:usize,curve:&FastCurveC)->bool{while self.batches.len()<=batch{let mut pts=Vec::with_capacity(64);while pts.len()<64&&self.next<NUM_TESTS{let count=(64-pts.len()).min(NUM_TESTS-self.next);let mut scalars=Vec::with_capacity(count*2);for i in self.next..self.next+count{let off=i*64;scalars.push(U256::from_le_slice(&self.keys[off..off+32]));scalars.push(U256::from_le_slice(&self.keys[off+32..off+64]));}self.next+=count;for(t,o,e)in curve.points_with_sums(&scalars){if t.0!=o.0&&!(t.0.is_zero()&&t.1.is_zero())&&!(o.0.is_zero()&&o.1.is_zero()){pts.push((t,o,e));}}}if pts.is_empty(){return false;}self.batches.push(pts);}true}
}
fn nonce_tail(tail:&[Op],nonce:u64)->Vec<Op>{assert!(nonce<1<<48);let mut t=tail.to_vec();for b in 0..48{t[2*b].q_target=QubitId((nonce>>b)&1);t[2*b+1].q_target=QubitId((nonce>>b)&1);}t}
fn tail_nonce_of(tail:&[Op])->u64{(0..48).map(|b|(tail[2*b].q_target.0&1)<<b).sum()}
fn exact_batch(p:&Compact,packets:&[Packet],indices:[usize;8],active:[bool;8],regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,rng:&[u64])->[&'static str;8]{
 let mut q=vec![0u64;nq*8];let mut b=vec![0u64;nb*8];let mut phase=[0u64;8];let mut stack=vec![0u64;4096*8];let mut used=0usize;
 for j in 0..8{if !active[j]{continue;}for(lane,(t,o,_))in packets[j].batches[indices[j]].iter().enumerate(){for(reg,value)in regs[..4].iter().zip([t.0,t.1,o.0,o.1]){for(i,wire)in reg.iter().enumerate(){let v=(value.bit(i)as u64)<<lane;match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j]|=v,QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]|=v}}}}}
 assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),q.as_mut_ptr(),b.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);
 let mut result=["inactive";8];for j in 0..8{if !active[j]{continue;}let pts=&packets[j].batches[indices[j]];let mask=if pts.len()==64{u64::MAX}else{(1u64<<pts.len())-1};let mut classical=false;
 for(lane,(_,_,expected))in pts.iter().enumerate(){for(reg,value)in regs[..2].iter().zip([expected.0,expected.1]){for(i,wire)in reg.iter().enumerate(){let raw=match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j],QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]};classical|=((raw>>lane)&1)!=(value.bit(i)as u64);}}}
 for reg in regs{for wire in reg{if let QubitOrBit::Qubit(id)=wire{q[id.0 as usize*8+j]=0;}}}let ancilla=(0..nq).any(|i|q[i*8+j]&mask!=0);result[j]=if classical{"classical"}else if phase[j]&mask!=0{"phase"}else if ancilla{"ancilla"}else{"pass"};}result
}

struct PreparedPacket{packet:Packet,ctx:Arc<Shake8>,lane:usize,nonce:u64,selected:usize,hit:bool,prepsecs:f64}
fn prepare8(base:&Shake8,hash:&Shake256,tail:&[Op],nonces:[u64;8],valid:[bool;8],curve:&FastCurveC,model:&RailAdvisory)->Vec<PreparedPacket>{
 let start=std::time::Instant::now();let mut encoded=Vec::with_capacity(TAIL*49*8);for nonce in nonces{for op in nonce_tail(tail,nonce){encoded.extend_from_slice(&record49(&op));}}let mut ctx=base.copy();ctx.different(&encoded,TAIL*49);ctx.finalize();let keys=ctx.squeeze(NUM_TESTS*64);
 for j in 0..8{let mut h=hash.clone();h.update(&encoded[j*TAIL*49..(j+1)*TAIL*49]);let mut check=[0u8;64];XofReader::read(&mut h.finalize_xof(),&mut check);assert_eq!(&check,&keys[j*NUM_TESTS*64..j*NUM_TESTS*64+64]);}let ctx=Arc::new(ctx);let mut result=Vec::new();
 for j in 0..8{if !valid[j]{continue;}let mut packet=Packet{keys:keys[j*NUM_TESTS*64..(j+1)*NUM_TESTS*64].to_vec(),next:0,batches:Vec::new()};let mut selected=0;let mut i=0;let mut hit=false;while packet.ensure(i,curve){if rail_suspect_many(model,&packet.batches[i]){selected=i;hit=true;break;}i+=1;}result.push(PreparedPacket{packet,ctx:ctx.clone(),lane:j,nonce:nonces[j],selected,hit,prepsecs:0.0});}let elapsed=start.elapsed().as_secs_f64();for p in&mut result{p.prepsecs=elapsed;}result
}
fn confirm_bucket(prefix:&Compact,mut prepared:Vec<PreparedPacket>,regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,curve:&FastCurveC)->Vec<serde_json::Value>{
 let start=std::time::Instant::now();assert!(!prepared.is_empty()&&prepared.len()<=8);let len=prepared.len();let contexts=std::array::from_fn(|j|prepared[j.min(len-1)].ctx.0 as *const c_void);let lanes=std::array::from_fn(|j|prepared[j.min(len-1)].lane as u32);let mut ctx=Shake8::combine(contexts,lanes);
 // Independent lane routing check before any batch-offset consumption.
 let mixed=ctx.copy().squeeze(64);for j in 0..len{let original=prepared[j].ctx.copy().squeeze(64);let lane=prepared[j].lane;assert_eq!(&mixed[j*64..(j+1)*64],&original[lane*64..(lane+1)*64],"regrouped nonce/lane route mismatch");}
 let indices=std::array::from_fn(|j|if j<len{prepared[j].selected}else{0});let valid=std::array::from_fn(|j|j<len);let nonces:Vec<_>=prepared.iter().map(|p|p.nonce).collect();let hits:Vec<_>=prepared.iter().map(|p|p.hit).collect();let prepsecs:Vec<_>=prepared.iter().map(|p|p.prepsecs).collect();let mut packets:Vec<_>=prepared.drain(..).map(|p|p.packet).collect();while packets.len()<8{packets.push(Packet{keys:Vec::new(),next:NUM_TESTS,batches:Vec::new()});}
 let mut selected=ctx.copy();let rngstart=std::time::Instant::now();let rng=selected.select(indices.map(|i|i*prefix.rng_count),prefix.rng_count);let rngsecs=rngstart.elapsed().as_secs_f64();let exactstart=std::time::Instant::now();let mut active=valid;for j in 0..8{active[j]&=packets[j].ensure(indices[j],curve);}let result=exact_batch(prefix,&packets,indices,active,regs,nq,nb,&rng);let exactsecs=exactstart.elapsed().as_secs_f64();drop(rng);let mut kinds=["pass";8];let mut witness=[None;8];let mut batches=[0;8];let mut remaining=valid;
 for j in 0..8{if active[j]{batches[j]+=1;if result[j]!="pass"{kinds[j]=result[j];witness[j]=Some(indices[j]);remaining[j]=false;}}else{remaining[j]=false;}}
 let mut i=0;while remaining.iter().any(|x|*x){let mut check=[false;8];for j in 0..8{if !remaining[j]{continue;}if !packets[j].ensure(i,curve){remaining[j]=false;continue;}check[j]=i!=indices[j];}let rng=ctx.words(prefix.rng_count);if check.iter().any(|x|*x){let results=exact_batch(prefix,&packets,[i;8],check,regs,nq,nb,&rng);for j in 0..8{if check[j]{batches[j]+=1;if results[j]!="pass"{kinds[j]=results[j];witness[j]=Some(i);remaining[j]=false;}}}}i+=1;}
 (0..len).map(|j|serde_json::json!({"nonce":nonces[j],"pass":witness[j].is_none(),"kind":kinds[j],"batches_run":batches[j],"exact_witness_batch":witness[j],"advisory_batch":indices[j],"advisory_hit":hits[j],"prepared_batches":packets[j].batches.len(),"bucket_size":len,"advisory_backend":"avx512_rails8","selected_rng_group_secs":rngsecs,"selected_exact_group_secs":exactsecs,"bucket_max_batch":*indices.iter().max().unwrap(),"preparation_group_secs":prepsecs[j],"confirmation_group_secs":start.elapsed().as_secs_f64(),"rejection_policy":"exact_full_state_only"})).collect()
}
fn baseline_main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),8,"OPS FIRST COUNT THREADS OUT MODEL_SOURCE LOOKAHEAD");let ops=load_ops(&a[1]).unwrap();let n=ops.len();let tail=ops[n-TAIL..].to_vec();for pair in tail.chunks_exact(2){assert_eq!(pair[0],pair[1]);assert_eq!(pair[0].kind,OperationType::X);assert_eq!(pair[0].c_condition.0,u64::MAX);}let own=tail_nonce_of(&tail);let(nq,nb,_,regs)=analyze_ops(ops.iter());let first=a[2].parse::<u64>().unwrap();let count=a[3].parse::<usize>().unwrap();let threads=a[4].parse::<usize>().unwrap();let lookahead=a[7].parse::<usize>().unwrap();assert!(threads>0&&threads<=16&&lookahead>0&&lookahead<=1024);
 let mut base=Shake8::new();let mut hash=Shake256::default();for bytes in [b"quantum_ecc-fiat-shamir-v2".as_slice(),&(n as u64).to_le_bytes()]{base.same(bytes);hash.update(bytes);}let mut encoded=Vec::with_capacity(49*32768);for op in &ops[..n-TAIL]{encoded.extend_from_slice(&record49(op));if encoded.len()>=49*32768{base.same(&encoded);hash.update(&encoded);encoded.clear();}}if !encoded.is_empty(){base.same(&encoded);hash.update(&encoded);}let p=Compact::compile(&ops[..n-TAIL]);let curve=FastCurveC::new(20);let model=RailAdvisory::new(&a[6]);let best=std::sync::atomic::AtomicU64::new(u64::MAX);let out=Mutex::new(File::create(&a[5]).unwrap());let started=std::time::Instant::now();let mut total_prep=0.0;let mut total_confirm=0.0;
 for window in (0..count).step_by(lookahead){let stop=(window+lookahead).min(count);if first+window as u64>best.load(Ordering::SeqCst){break;}let next=AtomicUsize::new(window);let prepared=Mutex::new(Vec::new());let t=std::time::Instant::now();std::thread::scope(|scope|{for _ in 0..threads{scope.spawn(||loop{let ix=next.fetch_add(8,Ordering::SeqCst);if ix>=stop{break;}let nonces=std::array::from_fn(|j|first+(ix+j).min(stop-1)as u64);let valid=std::array::from_fn(|j|ix+j<stop);let packets=prepare8(&base,&hash,&tail,nonces,valid,&curve,&model);prepared.lock().unwrap().extend(packets);} );}});total_prep+=t.elapsed().as_secs_f64();let mut prepared=prepared.into_inner().unwrap();prepared.sort_by_key(|x|(x.selected,x.nonce));let mut queue=std::collections::VecDeque::new();let mut iter=prepared.into_iter();loop{let group:Vec<_>=iter.by_ref().take(8).collect();if group.is_empty(){break;}queue.push_back(group);}let queue=Mutex::new(queue);let t=std::time::Instant::now();std::thread::scope(|scope|{for _ in 0..threads{scope.spawn(||loop{let group=queue.lock().unwrap().pop_front();let Some(group)=group else{break};for result in confirm_bucket(&p,group,&regs,nq as usize,nb as usize,&curve){if result["pass"]==true{best.fetch_min(result["nonce"].as_u64().unwrap(),Ordering::SeqCst);}writeln!(out.lock().unwrap(),"{result}").unwrap();}});}});total_confirm+=t.elapsed().as_secs_f64();}
 let b=best.load(Ordering::SeqCst);println!("BUCKET_SCREEN_DONE own={own} first={first} count={count} lookahead={lookahead} threads={threads} best={b} wall_seconds={:.6} preparation_seconds={total_prep:.6} confirmation_seconds={total_confirm:.6} exact_confirmation=true",started.elapsed().as_secs_f64());if b!=u64::MAX{let mut rewritten=ops[..n-TAIL].to_vec();rewritten.extend(nonce_tail(&tail,b));let r=run_tests(&rewritten,&regs,nq,nb,fiat_shamir_seed(&rewritten),NUM_TESTS);assert!(r.ok);println!("SELECTED_OFFICIAL_REPLAY nonce={b} ok={} shots={} classical={} phase={} ancilla={}",r.ok,r.n_shots,r.classical_failures,r.phase_garbage_batches,r.ancilla_garbage_batches);}}
